{
  "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
  "type": "AdaptiveCard",
  "version": "1.5",
  "body": [
    {
      "type": "TextBlock",
      "size": "Large",
      "weight": "Bolder",
      "id": "Title",
      "text": "Check List **@{outputs('Project_Checklist')?['body/vsb_name']}** meeting rejected for Project **@{outputs('Project')?['body/vsb_projectname']}**",
      "horizontalAlignment": "Left",
      "isSubtle": false,
      "style": "heading"
    },
    {
      "type": "TextBlock",
      "text": "Check List **@{outputs('Project_Checklist')?['body/vsb_name']}** meeting rejected for Project **@{outputs('Project')?['body/vsb_projectname']}** by Project Manager/ Developer @{outputs('Project_Manager')?['body/displayName']}, was rejected by Portfolio Manager @{outputs('Portfolio_Manager')?['body/displayName']}.\n\nRequest Due Date: @{outputs('Project_Checklist')?['body/vsb_approvalduedate']}\n\nRequest comment: @{outputs('Project_Checklist')?['body/vsb_approvalcomment']}\n",
      "wrap": true,
      "spacing": "Medium"
    },
    {
      "type": "Container",
      "items": [
        {
          "type": "TextBlock",
          "wrap": true,
          "height": "stretch"
        }
      ],
      "separator": true,
      "minHeight": "32px"
    },
    {
      "type": "TextBlock",
      "text": "Project details:",
      "weight": "Bolder",
      "size": "Large",
      "horizontalAlignment": "Left",
      "isSubtle": true
    },
    {
      "type": "ColumnSet",
      "spacing": "Small",
      "columns": [
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "Name",
              "weight": "Bolder",
              "style": "columnHeader"
            }
          ]
        },
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "Value",
              "weight": "Bolder",
              "style": "columnHeader"
            }
          ]
        }
      ]
    },
     @{join(variables('arrAdaptiveCardProjectDetails'),',')}
  ]
}

