{
    "$schema": "https://adaptivecards.io/schemas/adaptive-card.json",
    "type": "AdaptiveCard",
    "version": "1.5",
    "body": [
        {
            "type": "TextBlock",
            "size": "Large",
            "weight": "Bolder",
            "id": "Title",
            "text": "Initiate  voting for Project **@{outputs('Project')?['body/vsb_projectname']}** Check List **@{outputs('Project_Checklist')?['body/vsb_name']}**",
            "horizontalAlignment": "Left",
            "isSubtle": false,
            "style": "heading"
        },
        {
            "type": "TextBlock",
            "text": "Please confirm when the  meeting for Project @{outputs('Project')?['body/vsb_projectname']} Check List **@{outputs('Project_Checklist')?['body/vsb_name']}** took place in order to initiate voting.\n\nRequest Due Date: **@{formatDateTime(outputs('Project_Checklist')?['body/vsb_approvalduedate'],'ddd, MMM. dd, yyyy')}**\n\nRequest comment: @{outputs('Project_Checklist')?['body/vsb_approvalcomment']}\n",
            "wrap": true
        },
        {
            "id": "outGateMeetingDate",
            "type": "Input.Date",
            "errorMessage": "Please enter date, when gate meeting took place.",
            "placeholder": "Gate Meeting Date",
            "isRequired": true
        },
      {
      "type": "Container",
      "items": [
        {
          "type": "TextBlock",
          "wrap": true,
          "height": "stretch"
        }
      ],
      "separator": true,
      "minHeight": "32px"
    },
    {
      "type": "TextBlock",
      "text": "Project details:",
      "weight": "Bolder",
      "size": "Large",
      "horizontalAlignment": "Left",
      "isSubtle": true
    },
    {
      "type": "ColumnSet",
      "spacing": "Small",
      "columns": [
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "Name",
              "weight": "Bolder",
              "style": "columnHeader"
            }
          ]
        },
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "Value",
              "weight": "Bolder",
              "style": "columnHeader"
            }
          ]
        }
      ]
    },
     @{join(variables('arrAdaptiveCardProjectDetails'),',')}
    ],
    "actions": [
        {
            "type": "Action.Submit",
            "title": "Submit"
        }
    ],
    "verticalContentAlignment": "Center",
    "lang": "en"
}

